import{_ as e,o as s,c as i,a8 as t}from"./chunks/framework.DpsX1MbM.js";const k=JSON.parse('{"title":"EAGLE3 for Llama 3.1 8B: offline training","description":"","frontmatter":{},"headers":[],"relativePath":"examples/llama3-eagle3-offline.md","filePath":"sections/examples/llama3-eagle3-offline.md","lastUpdated":1788846900000}'),n={name:"examples/llama3-eagle3-offline.md"};function l(p,a,h,r,o,d){return s(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="eagle3-for-llama-3-1-8b-offline-training" tabindex="-1">EAGLE3 for Llama 3.1 8B: offline training <a class="header-anchor" href="#eagle3-for-llama-3-1-8b-offline-training" aria-label="Permalink to &quot;EAGLE3 for Llama 3.1 8B: offline training&quot;">​</a></h1><p>Offline training captures target features ahead of time and reads them from disk while training the draft. It reduces GPU memory pressure during training, but feature storage can be much larger than the source dataset.</p><h2 id="_1-prepare-sharegpt" tabindex="-1">1. Prepare ShareGPT <a class="header-anchor" href="#_1-prepare-sharegpt" aria-label="Permalink to &quot;1. Prepare ShareGPT&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./scripts/prepare_data.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dataset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sharegpt</span></span></code></pre></div><h2 id="_2-capture-hidden-states" tabindex="-1">2. Capture hidden states <a class="header-anchor" href="#_2-capture-hidden-states" aria-label="Permalink to &quot;2. Capture hidden states&quot;">​</a></h2><p>Feature preparation is a data-processing step, not a second training entry point:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">torchrun</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --standalone</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --nproc_per_node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  scripts/prepare_hidden_states.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --strategy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eagle3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --target-model-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meta-llama/Llama-3.1-8B-Instruct</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --draft-model-config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> configs/llama3-8B-eagle3.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --data-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./cache/dataset/sharegpt_train.jsonl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./cache/hidden_states/sharegpt_train_Llama-3.1-8B-Instruct</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --chat-template</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llama3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --max-length</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4096</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --tp-size</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --batch-size</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32</span></span></code></pre></div><p>The output directory now matches the hidden-state path in the checked-in recipe. It contains the feature checkpoints consumed by the unified trainer and <code>vocab_mapping/vocab_mapping.pt</code>, derived from the same processed corpus.</p><h2 id="_3-use-the-checked-in-run-config" tabindex="-1">3. Use the checked-in run config <a class="header-anchor" href="#_3-use-the-checked-in-run-config" aria-label="Permalink to &quot;3. Use the checked-in run config&quot;">​</a></h2><p>The canonical recipe is <a href="https://github.com/sgl-project/SpecForge/blob/main/examples/configs/offline/colocated/llama3.1-8b-eagle3-offline.yaml" target="_blank" rel="noreferrer"><code>examples/configs/offline/colocated/llama3.1-8b-eagle3-offline.yaml</code></a>. It records the same target, feature directory, draft architecture, and trainer settings used by this walkthrough; edit the checked-in recipe or use dotted overrides instead of copying its YAML into another document.</p><p>The recipe carries a conventional <code>model.vocab_mapping_path</code> for deployments that prepare and share a mapping artifact. For an offline colocated run, leaving that field empty makes SpecForge count effective tokens in the exact feature corpus, derive <code>t2d</code>/<code>d2t</code> deterministically, and cache the reusable mapping under <code>data.cache_dir/vocab_mapping</code>. Equal target and draft vocabularies need no mapping.</p><h2 id="_4-train" tabindex="-1">4. Train <a class="header-anchor" href="#_4-train" aria-label="Permalink to &quot;4. Train&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">specforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> train</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/configs/offline/colocated/llama3.1-8b-eagle3-offline.yaml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  model.vocab_mapping_path=./cache/hidden_states/sharegpt_train_Llama-3.1-8B-Instruct/vocab_mapping/vocab_mapping.pt</span></span></code></pre></div><p>Omit the final override when the mapping file named by the recipe already exists. The same recipe supports offline data parallelism through the typed <code>deployment.trainer</code> topology and unified self-launcher.</p><p>For long sequences, EAGLE3 offline can instead use USP by setting <code>training.attention_backend=usp</code> and choosing <code>training.sp_ulysses_size</code>/<code>training.sp_ring_size</code>. Offline feature training also supports DFlash, DFlash2, Domino, and DSpark when the feature checkpoints and draft config use that strategy&#39;s contract. <code>training.compact_teacher: true</code> enables the exact lower-memory teacher projection for offline text EAGLE3. See <a href="./../basic_usage/training.html#parallel-topologies">Parallel topologies</a> for the multi-process launch contract.</p>`,15)])])}const g=e(n,[["render",l]]);export{k as __pageData,g as default};
